// TestBrokenBuildRepackSweep — fix-episode-playback box 4.1, the Tier-1 joint
// for the healing chain: a published complete build corrupted on disk (a
// deleted tail segment + a window-truncated playlist — the exact shape the
// pre-fix lane left behind) must (a) flip the descriptor to the direct floor
// through the real guard, (b) be re-enqueued by the integrity sweep's
// snapshot + the real repack judge into the real packaging lane, and (c) come
// back as a fresh whole build whose descriptor answers hls again — then stay
// quiet, the stale corrupt build directory notwithstanding. Every hop a real
// instance: real scanner subprocess, real pack lane (ffmpeg), real
// ValidateBuild, real orchestrator.Repacks, real EnqueuePack, real descriptor
// handler over HTTP. cmd/mellifera is package main and cannot be imported, so
// the sweep's snapshot assembly is mirrored in miniature (the harness's
// established pattern); the decision itself is the production function.
package itest

import (
	"context"
	"encoding/json"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/orchestrator"
	"github.com/mellifera/mellifera/internal/stream"
)

func TestBrokenBuildRepackSweep(t *testing.T) {
	w := pbNewWorld(t)
	q := w.pbNewQueue(t, nil, 0) // plain real pack closure, production lease TTL
	enqueue := w.pbEnqueue(q)

	// --- scan: a one-episode serial library; the pilot pack runs the real lane ---
	libRoot := filepath.Join(t.TempDir(), "lib")
	show := filepath.Join(libRoot, "Broken Build Show")
	if err := os.MkdirAll(show, 0o755); err != nil {
		t.Fatalf("mkdir fixture: %v", err)
	}
	pbMakeMKV(t, filepath.Join(show, "Broken Build Show E01.mkv"), 5*time.Second, false)

	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Broken Build")
	res := pbScanLibrary(t, w, libID)
	if res.Discovered != 2 || res.Persisted != 2 {
		t.Fatalf("scan discovered=%d persisted=%d, want 2/2 (1 serial record + 1 episode); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	pbAwaitIdle(t, q, 30*time.Second) // metadata chain soft-fails (plugins unloaded); drain it

	byRel := pbItemByRel(t, w, libID)
	e01, ok := byRel["Broken Build Show/Broken Build Show E01.mkv"]
	if !ok || e01.ID == "" {
		t.Fatalf("E01 item missing; have %v", relKeys(byRel))
	}

	// --- the frontier fronts the pilot; the real lane publishes a complete build ---
	jobs := w.pbSweep(t, enqueue)
	if len(jobs) != 1 || jobs[0].ItemID != e01.ID || jobs[0].Reason != "pilot" {
		t.Fatalf("first sweep jobs = %+v, want exactly [pilot on E01 %s]", jobs, e01.ID)
	}
	streams := pbAwaitStreams(t, w.st, e01.ID, "complete", 60*time.Second)
	pbAwaitIdle(t, q, 30*time.Second)
	oldNonce, _ := streams["nonce"].(string)
	if oldNonce == "" {
		t.Fatalf("persisted streams missing nonce: %v", streams)
	}
	// Sanity: the build is born whole — the corruption below must break
	// something that was intact, not a build that never worked.
	if pb := pbDescriptor(t, w, e01.ID); pb.Mode != "hls" || pb.State != "complete" {
		t.Fatalf("descriptor before corruption = mode %q state %q, want hls/complete", pb.Mode, pb.State)
	}

	// --- corrupt the published build: one deleted tail segment + a playlist
	// truncated to its last window (ENDLIST kept — it still claims complete) ---
	pbCorruptTail(t, filepath.Join(w.root, e01.ID, oldNonce))

	// The descriptor's floor guard answers direct while the build is corrupt
	// (real GET; the stored packaging state is untouched).
	if pb := pbDescriptor(t, w, e01.ID); pb.Mode != "direct" || pb.State != "complete" {
		t.Fatalf("descriptor while corrupt = mode %q state %q, want direct/complete (the floor guard)", pb.Mode, pb.State)
	}

	// --- the integrity sweep validates the pointed-at build; the judge's
	// repack job re-enters the real packaging lane ---
	jobs = w.pbIntegritySweep(t, w.media.ValidateBuild, enqueue)
	if len(jobs) != 1 || jobs[0].ItemID != e01.ID || jobs[0].Reason != "repack" {
		t.Fatalf("integrity sweep jobs = %+v, want exactly [repack on E01 %s]", jobs, e01.ID)
	}
	pbAwaitIdle(t, q, 60*time.Second) // the repack drained AND persisted (persist precedes idle)

	streams = pbAwaitStreams(t, w.st, e01.ID, "complete", 60*time.Second)
	newNonce, _ := streams["nonce"].(string)
	if newNonce == "" || newNonce == oldNonce {
		t.Fatalf("repack did not publish a fresh build nonce: old %q, streams %v", oldNonce, streams)
	}

	// --- the fresh build satisfies the complete-build contract on disk truth
	// (never through ValidateBuild — the mechanism must not grade its own work) ---
	pbAssertWholeBuild(t, filepath.Join(w.root, e01.ID, newNonce))

	// The descriptor answers hls again, pointed at the fresh build, and the
	// playlist it hands the player actually serves.
	pb := pbDescriptor(t, w, e01.ID)
	if pb.Mode != "hls" || pb.State != "complete" {
		t.Fatalf("descriptor after repack = mode %q state %q, want hls/complete", pb.Mode, pb.State)
	}
	if !strings.Contains(pb.PlayURL, "/"+newNonce+"/index.m3u8?token=") {
		t.Fatalf("play URL = %q, want the fresh nonce's playlist with a token", pb.PlayURL)
	}
	plStatus, plBody, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+pb.PlayURL, "", nil)
	if plStatus != http.StatusOK || !strings.Contains(string(plBody), "#EXT-X-ENDLIST") {
		t.Fatalf("fresh playlist GET: status %d len %d, want 200 with the complete playlist", plStatus, len(plBody))
	}

	// --- loop safety: the healed item never re-jobs — the stale corrupt build
	// directory is still on disk, but the sweep validates what the doc points at ---
	if jobs := w.pbIntegritySweep(t, w.media.ValidateBuild, enqueue); len(jobs) != 0 {
		t.Fatalf("second integrity sweep jobs = %+v, want none (a healed item must not re-enqueue)", jobs)
	}
	pbAwaitIdle(t, q, 30*time.Second)
}

// pbIntegritySweep mirrors cmd/mellifera sweepIntegrity's snapshot assembly
// (the shell is package main): walk the artifact root's item dirs, keep the
// live rows whose stored streams state is complete, hand the pointed-at build
// to validate, then EXECUTE the judge's jobs through the real enqueue seam.
// The decision is the production orchestrator.Repacks — no mirror there.
func (w *pbWorld) pbIntegritySweep(t *testing.T, validate func(itemID, nonce string) error, enqueue func(string) error) []orchestrator.Job {
	t.Helper()
	ctx := context.Background()
	idDirs, err := os.ReadDir(w.root)
	if err != nil {
		t.Fatalf("integrity sweep walk root: %v", err)
	}
	items := make([]orchestrator.IntegrityItem, 0)
	for _, idDir := range idDirs {
		if !idDir.IsDir() {
			continue
		}
		row, err := w.st.GetItem(ctx, idDir.Name())
		if err != nil {
			continue // orphaned or unreadable: nothing live to heal
		}
		if row.Status == "deleted" {
			continue
		}
		var doc map[string]any
		_ = json.Unmarshal(row.Document, &doc)
		streams, _ := doc["streams"].(map[string]any)
		state, _ := streams["state"].(string)
		if state != stream.StateComplete {
			continue
		}
		nonce, _ := streams["nonce"].(string)
		items = append(items, orchestrator.IntegrityItem{
			ItemID: idDir.Name(), Healthy: validate(idDir.Name(), nonce) == nil,
		})
	}
	jobs := orchestrator.Repacks(items)
	for _, job := range jobs {
		if err := enqueue(job.ItemID); err != nil {
			t.Fatalf("integrity sweep enqueue %s: %v", job.ItemID, err)
		}
	}
	return jobs
}

// pbCorruptTail breaks one published complete build the way the pre-fix lane
// left broken builds on disk (fix-episode-playback R1's defect shape): one
// tail segment file is deleted (a playlist reference that would 404 in the
// player) and the playlist is truncated to a window of its LAST entries —
// earlier published segments stranded on disk, ENDLIST kept so the build
// still claims completeness. Asserts both defects are live before returning,
// so the caller's floor-guard assertion can never pass on an unbroken build.
func pbCorruptTail(t *testing.T, artDir string) {
	t.Helper()
	plPath := filepath.Join(artDir, "index.m3u8")
	raw, err := os.ReadFile(plPath)
	if err != nil {
		t.Fatalf("read published playlist: %v", err)
	}
	lines := strings.Split(strings.TrimRight(string(raw), "\n"), "\n")
	type entry struct {
		extinf    int // index of the entry's #EXTINF line (-1 when absent)
		uri       int // index of the entry's URI line
		hasExtinf bool
	}
	var entries []entry
	lastTail := "" // the playlist's last tail-segment URI
	for i, l := range lines {
		l = strings.TrimSpace(l)
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		e := entry{extinf: -1, uri: i}
		if i > 0 && strings.HasPrefix(strings.TrimSpace(lines[i-1]), "#EXTINF") {
			e.extinf, e.hasExtinf = i-1, true
		}
		entries = append(entries, e)
		if strings.HasPrefix(l, "t/") {
			lastTail = l
		}
	}
	// The hermetic 5s fixture yields a two-entry build (one head segment, one
	// tail segment — stream copy places no intermediate keyframes), so the
	// window may be the single last entry; both defects still land.
	if lastTail == "" || len(entries) < 2 {
		t.Fatalf("published playlist too small to corrupt (%d entries, last tail %q):\n%s", len(entries), lastTail, raw)
	}
	// Defect 1: delete the LAST tail segment — the entry the kept window still
	// references, so the reference resolves to a missing file.
	if err := os.Remove(filepath.Join(artDir, filepath.FromSlash(lastTail))); err != nil {
		t.Fatalf("delete tail segment %s: %v", lastTail, err)
	}
	// Defect 2: truncate to the last window (never the whole list) — the
	// dropped entries' segments stay published but unreferenced.
	keep := 2
	if keep > len(entries)-1 {
		keep = len(entries) - 1
	}
	dropped := entries[:len(entries)-keep]
	drop := map[int]bool{}
	for _, e := range entries[:len(entries)-keep] {
		if e.hasExtinf {
			drop[e.extinf] = true
		}
		drop[e.uri] = true
	}
	out := make([]string, 0, len(lines))
	for i, l := range lines {
		if !drop[i] {
			out = append(out, l)
		}
	}
	if err := os.WriteFile(plPath, []byte(strings.Join(out, "\n")+"\n"), 0o644); err != nil {
		t.Fatalf("write truncated playlist: %v", err)
	}
	// Both defects must be live: the kept window still references the deleted
	// segment, and at least one dropped segment is still published on disk.
	trunc, err := os.ReadFile(plPath)
	if err != nil {
		t.Fatalf("re-read truncated playlist: %v", err)
	}
	if !strings.Contains(string(trunc), lastTail) {
		t.Fatalf("truncated playlist lost the deleted segment's reference %s:\n%s", lastTail, trunc)
	}
	stranded := 0
	for _, e := range dropped {
		if _, err := os.Stat(filepath.Join(artDir, filepath.FromSlash(strings.TrimSpace(lines[e.uri])))); err == nil {
			stranded++
		}
	}
	if stranded == 0 {
		t.Fatalf("truncation stranded no published segment (window %d of %d entries):\n%s", keep, len(entries), trunc)
	}
}

// pbAssertWholeBuild asserts the complete-build contract directly against the
// disk (the same contract stream.ValidateBuild enforces, re-derived here so
// the healed build is judged independently of the mechanism being proven):
// every published playlist's references resolve to existing files relative to
// that playlist's own directory and never escape the build, and the complete
// (ENDLIST) playlist's referenced segment set EQUALS every published
// seg-*.m4s under the build directory.
func pbAssertWholeBuild(t *testing.T, dir string) {
	t.Helper()
	published := map[string]bool{}
	var playlists []string
	err := filepath.WalkDir(dir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(dir, p)
		if err != nil {
			return err
		}
		name := d.Name()
		switch {
		case strings.HasPrefix(name, "seg-") && strings.HasSuffix(name, ".m4s"):
			published[filepath.ToSlash(rel)] = true
		case strings.HasSuffix(name, ".m3u8"):
			playlists = append(playlists, p)
		}
		return nil
	})
	if err != nil {
		t.Fatalf("walk build %s: %v", dir, err)
	}
	if len(playlists) == 0 || len(published) == 0 {
		t.Fatalf("build %s: %d playlist(s), %d published segment(s), want non-empty both", dir, len(playlists), len(published))
	}
	referenced := map[string]bool{}
	complete := false
	for _, pl := range playlists {
		b, err := os.ReadFile(pl)
		if err != nil {
			t.Fatalf("read playlist %s: %v", pl, err)
		}
		base := filepath.Dir(pl)
		for _, line := range strings.Split(string(b), "\n") {
			line = strings.TrimSpace(line)
			uri := ""
			switch {
			case line == "":
				continue
			case strings.HasPrefix(line, "#EXT-X-ENDLIST"):
				complete = true
			case strings.HasPrefix(line, "#EXT-X-MAP"):
				if i := strings.Index(line, `URI="`); i >= 0 {
					rest := line[i+len(`URI="`):]
					if j := strings.Index(rest, `"`); j >= 0 {
						uri = rest[:j]
					}
				}
			case strings.HasPrefix(line, "#"):
			default:
				uri = line
			}
			if uri == "" {
				continue
			}
			resolved := filepath.Join(base, uri)
			if _, err := os.Stat(resolved); err != nil {
				t.Fatalf("playlist %s references %q: not found relative to the playlist dir (%v)", filepath.Base(pl), uri, err)
			}
			rel, err := filepath.Rel(dir, resolved)
			if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
				t.Fatalf("playlist %s references %q outside the build", filepath.Base(pl), uri)
			}
			baseName := filepath.Base(rel)
			if strings.HasPrefix(baseName, "seg-") && strings.HasSuffix(baseName, ".m4s") {
				referenced[filepath.ToSlash(rel)] = true
			}
		}
	}
	if !complete {
		t.Fatalf("build %s: no ENDLIST playlist found (want a complete build)", dir)
	}
	missing := make([]string, 0)
	for seg := range published {
		if !referenced[seg] {
			missing = append(missing, seg)
		}
	}
	if len(missing) > 0 {
		sort.Strings(missing)
		t.Fatalf("build %s: complete playlist omits %d published segment(s): %s", dir, len(missing), strings.Join(missing, ", "))
	}
}
